static int Add(int a, int b) {
    return a + b;
}

static void Main() {
    int r = Add(3, 4);
    Console.WriteLine(r);
}

static void Change(int x, int[] arr) {
    x = 100;
    arr[0] = 100;
}

static void Main() {
    int n = 1;
    int[] a = { 1, 2 };
    Change(n, a);
    Console.WriteLine(n + " " + a[0]);
}

static void Swap(ref int a, ref int b) {
    int t = a; a = b; b = t;
}

static void Main() {
    int x = 1, y = 2;
    Swap(ref x, ref y);
    Console.WriteLine(x + " " + y);
}

static int Fact(int n) {
    if (n <= 1) return 1;
    return n * Fact(n - 1);
}

static void Main() {
    Console.WriteLine(Fact(4));
}
